import { describe, expect, it, vi } from 'vitest';

// The citations module is generated by vite.config.ts when the site is built.
vi.mock('virtual:source-citations', () => ({ sourceCitations: {} }));

const { familyOf, sectionContents } = await import('#lib/server/section-contents.ts');

describe('the pages a page belongs with, for the side column', () => {
	it('knows the essays of Foundations and of Essays by their address', () => {
		expect(familyOf('/foundations')).toBe('foundations');
		expect(familyOf('/essays/first')).toBe('essays');
		expect(familyOf('/nations/navajo-nation')).toBeUndefined();
		expect(familyOf('/constructor')).toBeUndefined();
	});

	it('has nothing for a part it does not know', async () => {
		expect(await sectionContents('charter')).toBeUndefined();
		expect(await sectionContents('constructor')).toBeUndefined();
	});
});
